const data = $input.first().json;

const doctorName = data.doctor_name;
const startTime = data.appointment_start;
const endTime = data.appointment_end;
const email = data.gmail;
const code = data.code;
const patientName = data.patient_name;

return [
  {
    json: {
      message: `Hello ${patientName}, your appointment is booked with ${doctorName} on ${startTime} to ${endTime}. Your appointment code is ${code}. We have sent the code and other details to your number sms.`
    }
  }
];

// --------------------------------------------------
// INPUTS
// --------------------------------------------------

const doctors = $input.all().map(item => item.json);
const appointments = $('Select rows from a table1').all().map(item => item.json);
const req = $('Code in JavaScript8').first().json;

// --------------------------------------------------
// CONSTANTS
// --------------------------------------------------

const CLINIC_START = 8 * 60;   // 08:00
const CLINIC_END   = 22 * 60;  // 22:00
const SLOT_SIZE    = 30;        // 30-minute slots

// --------------------------------------------------
// HELPERS
// --------------------------------------------------

function normalizeName(name = "") {
  return name.toLowerCase().replace(/dr\.?\s*/g, "").trim();
}

function normalizeDate(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  const yyyy = d.getUTCFullYear();
  const mm   = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dd   = String(d.getUTCDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

function timeToMinutes(time = "") {
  const parts = time.split(":");
  const h = parseInt(parts[0]) || 0;
  const m = parseInt(parts[1]) || 0;
  return h * 60 + m;
}

function minutesToTime(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, "0");
  const m = String(mins % 60).padStart(2, "0");
  return `${h}:${m}`;
}

function formatTime12h(time24) {
  const [hStr, mStr] = time24.split(":");
  let h = parseInt(hStr);
  const m = mStr;
  const ampm = h >= 12 ? "PM" : "AM";
  h = h % 12 || 12;
  return `${h}:${m} ${ampm}`;
}

function formatDateFriendly(dateStr) {
  const d = new Date(dateStr + "T00:00:00Z");
  return d.toLocaleDateString("en-US", {
    weekday: "long", year: "numeric", month: "long", day: "numeric", timeZone: "UTC"
  });
}

// --------------------------------------------------
// SETUP
// --------------------------------------------------

const requestedDate    = normalizeDate(req.date);
const requestedMin     = timeToMinutes(req.start_time);
const preferredRaw     = req.preferred_doctor ? req.preferred_doctor.trim() : null;
const friendlyDate     = formatDateFriendly(requestedDate);
const requestedTime12h = formatTime12h(minutesToTime(requestedMin));

const allDoctorNames = doctors.map(d => d.name || d.doctor_name).filter(Boolean);

const doctorsToCheck = preferredRaw
  ? allDoctorNames.filter(d => normalizeName(d).includes(normalizeName(preferredRaw)))
  : allDoctorNames;

if (preferredRaw && doctorsToCheck.length === 0) {
  return [{
    json: {
      status: "DOCTOR_NOT_FOUND",
      message: `We couldn't find "${preferredRaw}" in our system. Please check the doctor's name and try again, or leave it blank to book with any available doctor.`,
      date: requestedDate,
      friendly_date: friendlyDate,
      requested_time: minutesToTime(requestedMin)
    }
  }];
}

// --------------------------------------------------
// CORE: Check if a slot is blocked
// --------------------------------------------------

function isSlotBlocked(slotStart, slotEnd, doctorName) {
  return appointments.some(appt => {
    if (normalizeName(appt.doctor_name) !== normalizeName(doctorName)) return false;
    if (normalizeDate(appt.appointment_day) !== requestedDate) return false;
    const apStart = timeToMinutes(appt.appointment_start);
    const apEnd   = timeToMinutes(appt.appointment_end);
    return slotStart < apEnd && slotEnd > apStart;
  });
}

// --------------------------------------------------
// STEP 1: Is requested time FREE?
// --------------------------------------------------

const requestedSlotEnd = requestedMin + SLOT_SIZE;
const freeAtRequested  = [];

for (const doctor of doctorsToCheck) {
  if (!isSlotBlocked(requestedMin, requestedSlotEnd, doctor)) {
    freeAtRequested.push(doctor);
  }
}

if (freeAtRequested.length > 0) {
  const chosen   = freeAtRequested[Math.floor(Math.random() * freeAtRequested.length)];
  const slot12h  = formatTime12h(minutesToTime(requestedMin));
  const slotEnd12h = formatTime12h(minutesToTime(requestedSlotEnd));

  return [{
    json: {
      status: "TIME_AVAILABLE",
      message: `Great news! Your requested slot on ${friendlyDate} at ${slot12h} – ${slotEnd12h} is available with ${chosen}. Shall I go ahead and confirm the booking?`,
      date: requestedDate,
      friendly_date: friendlyDate,
      slot: minutesToTime(requestedMin),
      slot_end: minutesToTime(requestedSlotEnd),
      slot_12h: slot12h,
      slot_end_12h: slotEnd12h,
      doctor_name: chosen
    }
  }];
}

// --------------------------------------------------
// STEP 2: Requested time BLOCKED — find next free slot
// --------------------------------------------------

const nextAvailable = [];

for (const doctor of doctorsToCheck) {
  for (
    let start = requestedMin + SLOT_SIZE;
    start + SLOT_SIZE <= CLINIC_END;
    start += SLOT_SIZE
  ) {
    const end = start + SLOT_SIZE;
    if (!isSlotBlocked(start, end, doctor)) {
      nextAvailable.push({ doctor, slotStart: start });
      break;
    }
  }
}

if (nextAvailable.length > 0) {
  nextAvailable.sort((a, b) => a.slotStart - b.slotStart);

  const soonest = nextAvailable[0].slotStart;
  const tied    = nextAvailable.filter(s => s.slotStart === soonest);
  const chosen  = tied[Math.floor(Math.random() * tied.length)];

  const nextSlot12h    = formatTime12h(minutesToTime(chosen.slotStart));
  const nextSlotEnd12h = formatTime12h(minutesToTime(chosen.slotStart + SLOT_SIZE));

  return [{
    json: {
      status: "NEXT_AVAILABLE",
      message: `The ${requestedTime12h} slot on ${friendlyDate} is fully booked. However, the next available slot is at ${nextSlot12h} – ${nextSlotEnd12h} with ${chosen.doctor}. Would you like to book that instead?`,
      date: requestedDate,
      friendly_date: friendlyDate,
      requested_time: minutesToTime(requestedMin),
      requested_time_12h: requestedTime12h,
      slot: minutesToTime(chosen.slotStart),
      slot_end: minutesToTime(chosen.slotStart + SLOT_SIZE),
      slot_12h: nextSlot12h,
      slot_end_12h: nextSlotEnd12h,
      doctor_name: chosen.doctor
    }
  }];
}

// --------------------------------------------------
// STEP 3: Fully booked
// --------------------------------------------------

const doctorLabel = preferredRaw || "any of our doctors";

return [{
  json: {
    status: "FULLY_BOOKED",
    message: `Unfortunately, there are no available slots remaining for ${doctorLabel} on ${friendlyDate} after ${requestedTime12h}. Please try a different date or contact the clinic directly for assistance.`,
    date: requestedDate,
    friendly_date: friendlyDate,
    requested_time: minutesToTime(requestedMin),
    requested_time_12h: requestedTime12h,
    doctor_name: preferredRaw || "Any doctor"
  }
}];

const items = $input.all();

const doctorNames = items.map(item => item.json.doctor_name);

return [
  {
    json: {
      sentence: `We have the following doctors available: ${doctorNames.join(', ')}.`
    }
  }
];

return [
  {
    json: {
      message: "Yes, you can create an appointment"
    }
  }
];

const raw = $input.first()?.json?.raw_output;

if (!raw) {
  throw new Error("No raw_output found in input");
}

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error("Invalid JSON in raw_output");
}

// Extract values
const name = parsed.tool_name;

return [
  {
    json: {
      name: name,
      date: parsed.date || null,
      start_time: parsed.start_time || null,
      preferred_doctor: parsed.preferred_doctor || null
    }
  }
];

const data = $json.parsed_output;

if (!data) {
  return [{ json: { error: "No parsed output found" } }];
}

// --------------------------------------------------
// HELPER: ADD 30 MINUTES
// --------------------------------------------------
function add30Minutes(time) {
  if (!time) return "";
  const [h, m] = time.split(":").map(Number);
  const total = h * 60 + m + 30;
  const nh = Math.floor(total / 60) % 24;
  const nm = total % 60;
  return String(nh).padStart(2, "0") + ":" + String(nm).padStart(2, "0");
}

// --------------------------------------------------
// OUTPUT
// --------------------------------------------------
return [
  {
    json: {
      action: data.tool_name || "",
      patient_name: data.patient_name || "",
      doctor_name: data.doctor_name || "",
      date: data.date || "",
      time: data.time || "",
      appointment_end: add30Minutes(data.time),
      appointment_code: data.appointment_code || "",
      patient_phone: data.patient_phone || ""
    }
  }
];

// Try parsed_output first, fallback to parsing raw_output
let parsed = $json.parsed_output;

if (!parsed && $json.raw_output) {
  try {
    parsed = JSON.parse($json.raw_output);
  } catch (e) {
    return [{ json: { error: "Invalid raw_output JSON" } }];
  }
}

if (!parsed) {
  return [{ json: { error: "No parsed output found" } }];
}

return [
  {
    json: {
      appointment_code: parsed.appointment_code || null,
      patient_name: parsed.patient_name || null,
      patient_phone: parsed.patient_phone || null,
      tool_name: parsed.tool_name || null
    }
  }
];

return items.map(item => {
  let parsed = {};

  // Step 1: Safely parse JSON
  try {
    if (typeof item.json.output === "string") {
      parsed = JSON.parse(item.json.output);
    } else if (typeof item.json.output === "object" && item.json.output !== null) {
      parsed = item.json.output;
    }
  } catch (e) {
    parsed = {};
  }

  // Step 2: Normalize fields with fallbacks
  const tool_name = parsed.tool_name || parsed.tool || "unknown_tool";
  const message = parsed.message || parsed.text || "";

  // Step 3: Return clean + extensible structure
  return {
    json: {
      success: Object.keys(parsed).length > 0,
      tool_name,
      message,
      raw_output: item.json.output,   // keep original (debugging)
      parsed_output: parsed          // full parsed object (future use)
    }
  };
});

return items.map((item, index) => {
  let message = "";

  try {
    // Priority 1: direct message
    if (item.json.message) {
      message = item.json.message;
    }
    // Priority 2: parsed_output
    else if (item.json.parsed_output?.message) {
      message = item.json.parsed_output.message;
    }
    // Priority 3: raw_output (stringified JSON)
    else if (item.json.raw_output) {
      const parsed = JSON.parse(item.json.raw_output);
      message = parsed.message || "";
    }
    // Priority 4: sentence from first input
    else if ($input.first()?.json?.sentence) {
      message = $input.first().json.sentence;
    }

    // Fix line breaks
    message = message.replace(/\\n/g, '\n').trim();

  } catch (e) {
    message = "Something went wrong.";
  }

  return {
    json: {
      message
    }
  };
});

// Get input from previous node
const items = $input.all();
const inputData = items[0].json;

// Check if appointment was found and deleted
const isEmpty = Object.keys(inputData).length === 0;

let responseMessage;

if (isEmpty) {
  // No appointment found - code didn't match
  responseMessage = {
    success: false,
    status: "not_found",
    message: "❌ No appointment found with this code. Please check your cancellation code and try again.",
    code: null,
    cancelled: false
  };
} else {
  // Appointment was successfully deleted
  responseMessage = {
    success: true,
    status: "cancelled",
    message: "✅ Your appointment has been successfully cancelled.",
    code: inputData.code || null,
    cancelled: true,
    cancelledAt: new Date().toISOString()
  };
}

return [{ json: responseMessage }];
